// HASH MAP INTERNALS — chaining implementation
class HashMap {
    constructor(initialCapacity = 16, loadFactor = 0.75) {
        this.capacity = initialCapacity;
        this.loadFactor = loadFactor;
        this.size = 0;
        this.buckets = Array.from({length: this.capacity}, () => []); // chaining
    }

    _hash(key) {
        let hash = 0;
        for (const c of String(key)) hash = (hash * 31 + c.charCodeAt(0)) % this.capacity;
        return hash;
    }

    set(key, value) {
        const idx = this._hash(key);
        const bucket = this.buckets[idx];
        for (const pair of bucket) {
            if (pair[0] === key) { pair[1] = value; return; } // update
        }
        bucket.push([key, value]); // insert
        this.size++;
        if (this.size / this.capacity > this.loadFactor) this._rehash();
    }

    get(key) {
        const bucket = this.buckets[this._hash(key)];
        for (const [k, v] of bucket) if (k === key) return v;
        return undefined;
    }

    _rehash() {
        const oldBuckets = this.buckets;
        this.capacity *= 2;
        this.buckets = Array.from({length: this.capacity}, () => []);
        this.size = 0;
        for (const bucket of oldBuckets)
            for (const [k, v] of bucket) this.set(k, v);
    }
}

const hm = new HashMap();
hm.set('user:1', {name:'Alice', age:30});
hm.set('user:2', {name:'Bob', age:25});
console.log(hm.get('user:1')); // {name:'Alice',age:30}

// HASH JOIN SIMULATION
function hashJoin(tableA, tableB, keyA, keyB) {
    // Build phase: hash the smaller table
    const hashTable = new Map();
    for (const rowA of tableA) {
        const k = rowA[keyA];
        if (!hashTable.has(k)) hashTable.set(k, []);
        hashTable.get(k).push(rowA);
    }
    // Probe phase: scan larger table
    const result = [];
    for (const rowB of tableB) {
        const matches = hashTable.get(rowB[keyB]) || [];
        for (const rowA of matches) result.push({...rowA, ...rowB});
    }
    return result;
}

