// CONSISTENT HASHING with virtual nodes
class ConsistentHash {
    constructor(virtualNodes = 150) {
        this.virtualNodes = virtualNodes;
        this.ring = [];         // sorted array of {hash, node}
        this.nodeMap = new Map(); // node -> set of hash positions
    }

    _hash(key) {
        // Simple hash function (production uses MD5/SHA1)
        let h = 0;
        for (const c of String(key)) h = (h * 31 + c.charCodeAt(0)) >>> 0;
        return h;
    }

    addNode(node) {
        const positions = [];
        for (let i = 0; i < this.virtualNodes; i++) {
            const hash = this._hash(`${node}:vnode:${i}`);
            positions.push(hash);
            this.ring.push({hash, node});
        }
        this.ring.sort((a,b) => a.hash - b.hash);
        this.nodeMap.set(node, positions);
    }

    removeNode(node) {
        const positions = new Set(this.nodeMap.get(node) || []);
        this.ring = this.ring.filter(e => !positions.has(e.hash));
        this.nodeMap.delete(node);
    }

    getNode(key) {
        if (!this.ring.length) return null;
        const hash = this._hash(key);
        // Binary search for first ring position >= hash
        let lo = 0, hi = this.ring.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (this.ring[mid].hash < hash) lo = mid + 1;
            else hi = mid;
        }
        // Wrap around (circular ring)
        const idx = lo % this.ring.length;
        return this.ring[idx].node;
    }
}

const ch = new ConsistentHash(150);
ch.addNode('server-A');
ch.addNode('server-B');
