// BLOOM FILTER implementation
class BloomFilter {
    constructor(m, k) {
        this.m = m;         // bit array size
        this.k = k;         // number of hash functions
        this.bits = new Uint8Array(Math.ceil(m / 8)); // packed bits
    }

    // Simulate k hash functions using double hashing: h_i(x) = (h1(x) + i*h2(x)) % m
    _hashes(key) {
        const s = String(key);
        let h1 = 0, h2 = 0;
        for (const c of s) {
            h1 = (h1 * 31 + c.charCodeAt(0)) >>> 0;
            h2 = (h2 * 37 + c.charCodeAt(0)) >>> 0;
        }
        const positions = [];
        for (let i = 0; i < this.k; i++) {
            positions.push(((h1 + i * h2) >>> 0) % this.m);
        }
        return positions;
    }

    _getBit(pos)     { return (this.bits[pos >> 3] >> (pos & 7)) & 1; }
    _setBit(pos)     { this.bits[pos >> 3] |= 1 << (pos & 7); }

    add(key) {
        for (const pos of this._hashes(key)) this._setBit(pos);
    }

    mightContain(key) {
        return this._hashes(key).every(pos => this._getBit(pos) === 1);
    }

    // OPTIMAL PARAMETERS for n elements and desired false positive rate p
    static optimalParams(n, p) {
        const m = Math.ceil(-n * Math.log(p) / (Math.LN2 ** 2));
        const k = Math.round((m / n) * Math.LN2);
        return { m, k, expectedFPRate: (1 - Math.exp(-k*n/m)) ** k };
    }
}

// TEST
const params = BloomFilter.optimalParams(1_000_000, 0.01);
console.log(`Optimal for 1M elements, 1% FP: m=${params.m} bits (${(params.m/8/1024).toFixed(0)}KB), k=${params.k}`);
// m ≈ 9,585,059 bits (1170KB ≈ 1.1MB), k ≈ 7

const bf = new BloomFilter(params.m, params.k);
bf.add('user:alice@example.com');
bf.add('user:bob@example.com');

console.log(bf.mightContain('user:alice@example.com')); // true
console.log(bf.mightContain('user:charlie@example.com')); // false (probably)
console.log(bf.mightContain('user:nonexistent@test.com')); // false (probably)

// FALSE POSITIVE RATE VERIFICATION (simulation)
let falsePositives = 0;
for (let i = 0; i < 10000; i++) {
    if (bf.mightContain(`test:${i}`)) falsePositives++;
}
console.log(`False positive rate: ${(falsePositives/10000*100).toFixed(2)}%`); // should be ~1%

