// LRU CACHE (#146) — O(1) get and put
class LRUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.map = new Map();   // key -> node
        // Sentinel head/tail nodes for DLL
        this.head = {key:null, val:null, prev:null, next:null};
        this.tail = {key:null, val:null, prev:null, next:null};
        this.head.next = this.tail;
        this.tail.prev = this.head;
    }

    _remove(node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    _insertFront(node) {
        node.next = this.head.next;
        node.prev = this.head;
        this.head.next.prev = node;
        this.head.next = node;
    }

    get(key) {
        if (!this.map.has(key)) return -1;
        const node = this.map.get(key);
        this._remove(node);     // move to front
        this._insertFront(node);
        return node.val;
    }

    put(key, value) {
        if (this.map.has(key)) {
            const node = this.map.get(key);
            node.val = value;
            this._remove(node);
            this._insertFront(node);
        } else {
            if (this.map.size === this.capacity) {
                const lru = this.tail.prev; // LRU at tail
                this._remove(lru);
                this.map.delete(lru.key);
            }
            const node = {key, val:value, prev:null, next:null};
            this._insertFront(node);
            this.map.set(key, node);
        }
    }
}

// TEST LRU
const lru = new LRUCache(2);
lru.put(1, 1);  // cache: {1:1}
lru.put(2, 2);  // cache: {1:1, 2:2}
console.log(lru.get(1)); // 1, cache: {2:2, 1:1}
lru.put(3, 3);  // evicts 2, cache: {1:1, 3:3}
console.log(lru.get(2)); // -1 (evicted)
console.log(lru.get(3)); // 3

// LFU CACHE (#460) — O(1) get and put (abbreviated)
class LFUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.keyMap  = new Map(); // key -> {val, freq}
        this.freqMap = new Map(); // freq -> LinkedHashSet of keys
        this.minFreq = 0;
    }

    _getOrCreate(freq) {
        if (!this.freqMap.has(freq)) this.freqMap.set(freq, new Map()); // ordered Map = DLL
        return this.freqMap.get(freq);
    }

    _touch(key) {
        const {val, freq} = this.keyMap.get(key);
        this.freqMap.get(freq).delete(key);
        if (freq === this.minFreq && this.freqMap.get(freq).size === 0) this.minFreq++;
        const newFreq = freq + 1;
        this.keyMap.set(key, {val, freq: newFreq});
        this._getOrCreate(newFreq).set(key, true);
    }

    get(key) {
        if (!this.keyMap.has(key)) return -1;
        this._touch(key);
        return this.keyMap.get(key).val;
    }

    put(key, value) {
        if (this.capacity <= 0) return;
        if (this.keyMap.has(key)) {
            this.keyMap.get(key).val = value;
            this._touch(key); return;
        }
        if (this.keyMap.size === this.capacity) {
            const evictKey = this.freqMap.get(this.minFreq).keys().next().value;
            this.freqMap.get(this.minFreq).delete(evictKey);
            this.keyMap.delete(evictKey);
        }
        this.keyMap.set(key, {val: value, freq: 1});
        this._getOrCreate(1).set(key, true);
        this.minFreq = 1;
    }
}

