  if(requirement.includes('distributed')||requirement.includes('sharding'))return'Consistent Hashing';
  if(requirement.includes('membership'))return'Bloom Filter';
  if(requirement.includes('cache'))return'LRU/LFU Cache';
  if(requirement.includes('aggregates')||requirement.includes('range aggregates'))return'Segment/Fenwick Tree';
  return'HashMap';
}

function module7Summary(){
  return{total:MODULE7.length,nc150:MODULE7.filter(p=>p.nc150).length};
}
